'use strict';
let data, profile='G3', category='All subjects', comboId='g3pure', selections={}, optional=[], subjectLevels={};
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const subj=id=>data.subjects.find(s=>s.subject_id===id), name=id=>subj(id)?.subject_name||data.combinations.find(c=>c.combination_id===id)?.combination_name||id;
const current=()=>data.combinations.find(c=>c.combination_id===comboId);
function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function modal(html){$('modal-content').innerHTML=html;$('modal').showModal();}
function eligible(id,level){return data.eligibility.filter(e=>e.active&&e.subject_id===id&&e.subject_level===level).map(e=>e.eligibility_text);}
function criteria(ids,level){const entries=[...new Set(ids)].flatMap(id=>eligible(id,level).map(t=>`<p><b>${esc(name(id))}</b><br>${esc(t)}</p>`));return entries.length?`<details class="eligibility"><summary>ⓘ School eligibility criteria</summary>${entries.join('')}</details>`:'';}
function setProfile(p){profile=p;comboId=data.combinations.find(c=>c.active&&c.profile===p)?.combination_id;selections={};optional=[];subjectLevels={};renderProfile();renderCombinations();renderExplore();renderBuilder();}
function renderSubjectFaq(){let number=0;document.querySelectorAll('#subject-faq .subject-faq-item').forEach(item=>{item.hidden=(item.dataset.hideProfiles||'').split(' ').includes(profile);if(item.hidden){item.open=false;return;}const summary=item.querySelector('summary');summary.textContent=++number+'. '+summary.textContent.replace(/^\d+\.\s*/, '');});}
function renderProfile(){renderSubjectFaq();$('profiles').innerHTML=['G3','G2','G1'].map((p,i)=>`<button class="profile ${p===profile?'active':''}" aria-pressed="${p===profile}" data-profile="${p}"><span class="profile-dot"></span><span class="profile-code">0${i+1}</span><b>Mostly ${p} subjects</b><small>${{G3:'Explore Pure and Combined Science combinations',G2:'Explore your Science, Humanities and elective choices',G1:'Explore your core subjects and other subject choices'}[p]}</small></button>`).join('');$('profile-label').textContent='Mostly '+profile+' subjects';}
function renderCombinations(){const list=data.combinations.filter(c=>c.active&&c.profile===profile);$('combination-cards').innerHTML=list.map(c=>`<article class="combination-card"><span class="tag">${esc(c.profile)}</span><h3>${esc(c.combination_name)}</h3><p>${esc(c.description)}</p><p class="core-subjects-label"><b>Core subjects:</b></p><ol class="core-subjects-list">${c.compulsory.map(id=>`<li>${id==='ss'&&c.groups.some(g=>g.id==='humanities')?`Humanities (Social Studies + one elective)<br><span class="humanities-choice">Choose: ${c.groups.find(g=>g.id==='humanities').options.map(name).map(esc).join(' / ')}</span>`:esc(name(id))}</li>`).join('')}</ol><ul>${c.groups.filter(g=>!(g.id==='humanities'&&c.compulsory.includes('ss'))).map(g=>`<li><b>${g.options.length===1?'Included:':'Choose:'}</b> ${g.options.map(name).map(esc).join(' / ')}</li>`).join('')}${c.optional.length?`<li><b>Optional:</b> ${c.optional.map(name).map(esc).join(' / ')}</li>`:''}</ul>${optionalGroups(c).map(g=>`<p><b>${esc(g.label)}:</b> ${g.options.map(name).map(esc).join(' or ')} (choose one, or none).</p>`).join('')}${criteria([c.combination_id],profile)}<button class="button outline" data-build="${esc(c.combination_id)}">Try this combination →</button></article>`).join('');}
function optionalGroups(c){return c.optional_groups||[];}
function optionalSubjectIds(c){return [...c.optional,...optionalGroups(c).flatMap(g=>g.options)];}
function available(){const ids=new Set();data.combinations.filter(c=>c.active&&c.profile===profile).forEach(c=>{c.groups.forEach(g=>g.options.forEach(x=>ids.add(x)));c.compulsory.filter(x=>subj(x)?.full_description).forEach(x=>ids.add(x));optionalSubjectIds(c).forEach(x=>ids.add(x));});return data.subjects.filter(s=>s.active&&ids.has(s.subject_id));}
const icons={'Humanities':'◎','Science':'⚗','Mathematics':'ƒ','Creative & applied':'✧','Business':'▤','Computing':'⌘','Core':'↗'};
